3	/**
4	 * This class collects and provides some statistical data on the state
5	 * of a field. It is flexible: it will create and maintain a counter
6	 * for any class of object that is found within the field.
7	 *
8	 * @version 18.02.22 (DD:MM:YY)
9	 */
10	public class FieldStats
11	{
12	    // Counters for each type of actor in the simulation:
13	    private HashMap<Class<?>, Counter> counters;
14	    // Whether the counters are currently up to date:
15	    private boolean areCountsValid;
16	
17	    /**
18	     * Construct a FieldStats object.
19	     */
20	    public FieldStats()
21	    {
22	        counters = new HashMap<>();
23	        areCountsValid = true;
24	    }
25	
26	    /**
27	     * @return A string describing what is in the field.
28	     */
29	    public String getPopulationDetails(Field field)
30	    {
31	        if (!areCountsValid) generateCounts(field);
32	
33	        StringBuilder buffer = new StringBuilder();
34	        String prefix = "";
35	
36	        for (Counter info : counters.values())
37	        {
38	            buffer.append(prefix);
39	            buffer.append(info.getName());
40	            buffer.append(": ");
41	            buffer.append(info.getCount());
42	            prefix = ", ";
43	        }
44	
45	        return buffer.toString();
46	    }
47	
48	    /**
49	     * @return The counters representing population numbers.
50	     */
51	    public HashMap<Class<?>, Counter> getCounters(Field field)
52	    {
53	        if (!areCountsValid) generateCounts(field);
54	        return counters;
55	    }
56	
57	    /**
58	     * Invalidate the current set of statistics; reset all
59	     * counts to zero.
60	     */
61	    public void reset()
62	    {
63	        areCountsValid = false;
64	
65	        for (Counter count : counters.values())
66	        {
67	            count.reset();
68	        }
69	    }
70	
71	    /**
72	     * Increment the count for one class of actor.
73	     *
74	     * @param actorClass The class of actor to increment.
75	     */
76	    public void incrementCount(Class<?> actorClass)
77	    {
78	        Counter count = counters.get(actorClass);
79	
80	        if (count == null)
81	        {
82	            count = new Counter(actorClass.getName());
83	            counters.put(actorClass, count);
84	        }
85	
86	        count.increment();
87	    }
88	
89	    /**
90	     * Indicate that an actor count has been completed.
91	     */
92	    public void countFinished() { areCountsValid = true; }
93	
94	    /**
95	     * Determine whether the simulation is still viable.
96	     * I.e., should it continue to run.
97	     *
98	     * @return True if there is more than one species alive.
99	     */
100	    public boolean isViable(Field field)
101	    {
102	        if (!areCountsValid) generateCounts(field);
103	
104	        int nonZero = 0;
105	        for (Counter info : counters.values())
106	        {
107	            if (info.getCount() > 0) nonZero++;
108	        }
109	
110	        return nonZero > 1;
111	    }
112	
113	    /**
114	     * Generate counts of the number of actors.
115	     * These are not kept up to date as actors are placed in the
116	     * field, but only when a request is made for the information.
117	     *
118	     * @param field The field to generate the stats for.
119	     */
120	    private void generateCounts(Field field)
121	    {
122	        reset();
123	
124	        for (int row = 0; row < field.getDepth(); row++)
125	        {
126	            for (int col = 0; col < field.getWidth(); col++)
127	            {
128	                Object actor = field.getObjectAt(row, col);
129	                if (actor != null) incrementCount(actor.getClass());
130	            }
131	        }
132	
133	        areCountsValid = true;
134	    }
135	}
